css:
.resume{--page-width: 210mm;
      --page-height: 297mm;
      --bg-main: #FFFFFF;
      --text-primary: #2E2E2C;
      --text-secondary: #4B4B4B;
      --text-muted: #5F5F5D;
      --accent-burnt-orange: #C26A4B;
      --accent-soft-terracotta: #D98C6B;
      --line-light: #EAE6E1;
      --line-soft: #D9D2C7;
      --surface-warm: #FDF9F5;
      --highlight-cream: #FEF7F2;
      --shadow-subtle: 0 4px 10px rgba(0,0,0,0.03);}
.hand-drawn-border{position: absolute;
      top: 18px;
      left: 18px;
      right: 18px;
      bottom: 18px;
      border: 1.2px solid #D8CFC4;
      border-radius: 2px 80% 2px 80% / 2px 85% 2px 85%;
      pointer-events: none;
      opacity: 0.7;
      z-index: 1;}
.main-content{position: relative;
      z-index: 5;
      padding: 2.2rem 2.4rem 2rem 2.4rem;
      background: transparent;}
.resume h1, .resume h2, .resume h3, .resume p, .resume span, .resume li, .resume div{font-weight: normal;
      color: inherit;}
.name-section{margin-bottom: 1.5rem;
      border-bottom: 1.8px dashed var(--accent-burnt-orange);
      padding-bottom: 1.2rem;
      display: flex;
      flex-wrap: wrap;
      align-items: baseline;
      justify-content: space-between;}
.name{font-size: 2.8rem;
      font-family: 'Helvetica Neue', 'Arial', '思源黑体', sans-serif;
      font-weight: 350;
      letter-spacing: 0.04em;
      color: #2B2A28;
      line-height: 1.1;
      margin-right: 1rem;}
.title-sub{font-size: 1.1rem;
      font-weight: 380;
      color: var(--accent-burnt-orange);
      letter-spacing: 0.5px;
      font-family: 'Arial', 'Helvetica Neue', '思源黑体', sans-serif;
      background: rgba(253, 249, 245, 0.9);
      padding: 0.2rem 0.6rem;
      border-radius: 12px 4px 12px 4px;
      white-space: nowrap;}
.contact-row{display: flex;
      flex-wrap: wrap;
      gap: 1.8rem;
      margin-top: 0.5rem;
      font-size: 0.9rem;
      color: var(--text-secondary);
      align-items: center;}
.contact-item{display: flex;
      align-items: center;
      gap: 0.3rem;}
.contact-icon{font-size: 1rem;
      display: inline;
      margin-right: 0.15rem;
      color: var(--accent-soft-terracotta);
      font-weight: 400;}
.section-title{font-size: 1.1rem;
      font-weight: 500;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: #3D3D3B;
      margin: 1.8rem 0 0.9rem 0;
      border-bottom: 1px solid var(--line-light);
      padding-bottom: 0.25rem;
      display: flex;
      align-items: center;
      font-family: 'Helvetica Neue', 'Arial', '思源黑体', sans-serif;}
.section-title::after{content: "";
      display: inline-block;
      width: 28px;
      height: 1px;
      background: var(--accent-burnt-orange);
      margin-left: 0.7rem;
      opacity: 0.7;
      transform: translateY(-1px);}
.entry{margin-bottom: 1.2rem;}
.entry-header{display: flex;
      justify-content: space-between;
      align-items: baseline;
      flex-wrap: wrap;
      margin-bottom: 0.2rem;}
.institution{font-weight: 600;
      font-size: 1rem;
      color: #22211F;
      letter-spacing: 0.01em;}
.job-title{font-weight: 500;
      font-size: 0.95rem;
      color: var(--text-secondary);
      margin-left: 0.3rem;}
.date-location{font-size: 0.85rem;
      color: var(--text-muted);
      white-space: nowrap;
      font-weight: 400;}
.description{margin-top: 0.3rem;
      padding-left: 0.2rem;}
.desc-item{font-size: 0.9rem;
      color: #3E3E3C;
      margin-bottom: 0.25rem;
      display: flex;
      align-items: flex-start;
      gap: 0.5rem;}
.desc-item::before{content: "•";
      color: var(--accent-burnt-orange);
      font-weight: 500;
      font-size: 1.1rem;
      display: inline-block;
      width: 0.9rem;
      flex-shrink: 0;}
.skill-tags{display: flex;
      flex-wrap: wrap;
      gap: 0.5rem 0.8rem;
      margin-top: 0.3rem;}
.skill{background: var(--surface-warm);
      border: 1px solid #E8DDD2;
      border-radius: 20px 4px 20px 4px;
      padding: 0.25rem 1rem;
      font-size: 0.85rem;
      color: #3D3833;
      letter-spacing: 0.02em;
      white-space: nowrap;}
.two-columns{display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1.2rem 1.8rem;
      margin-top: 0.2rem;}
.column-item{font-size: 0.9rem;
      display: flex;
      align-items: baseline;
      gap: 0.4rem;
      color: #3E3E3C;}
.column-item strong{font-weight: 550;
      color: #2B2A28;
      min-width: 4.2rem;}
.link-text{color: var(--text-secondary);
      text-decoration: none;
      border-bottom: 1px dotted var(--accent-burnt-orange);
      font-weight: 400;}

.resume{width:210mm;min-height:297mm;background:#FFFFFF;margin:0 auto;box-shadow:0 12px 30px rgba(0,0,0,0.08);font-family:Arial,"Helvetica Neue","思源黑体","Source Han Sans SC",sans-serif;color:#2E2E2C;line-height:1.5;position:relative;border-radius:4px;overflow:hidden}.resume-title{font-size:9pt;letter-spacing:0.1em;color:#C26A4B;margin-bottom:10px}.summary{font-size:0.92rem;color:#3E3E3C;line-height:1.6;max-width:95%;margin-bottom:0.5rem}.skill-value{margin-left:6px}.pub-item{display:flex;flex-wrap:wrap;gap:1.2rem;align-items:baseline;font-size:0.9rem;margin-bottom:6px}.pub-name{font-weight:600}.pub-role{color:#5F5F5D}.award-line{display:flex;gap:1.5rem;margin-top:0.8rem;color:#5D5B58;font-size:0.85rem}.footer-note{margin-top:1.5rem;border-top:1px dashed #D9D2C7;padding-top:0.8rem;font-size:0.85rem;color:#5F5F5D;display:flex;justify-content:space-between}
